/// <summary>
/// Bug 284448: CB705 - Vendor Claims external data source does not link the transaction to METExternalSellData table
/// custom TAMRebateQueryBuilder to change the source of transaction to METRebateScanSupplierTable where CustAccount is populated
/// </summary>
using System.ComponentModel.Composition;
[ExportAttribute(identifierStr(Dynamics.AX.Application.TAMRebateQueryBuilder))]
[ExportMetadata(enumStr(ModuleInventCustVend), enumLiteralStr(ModuleInventCustVend, Cust))]
[ExportMetadata(enumStr(TAMRebateSourceType), enumLiteralStr(TAMRebateSourceType, METExternalSalesData))]
public final class METTAMRebateQueryBuilderCustExternalData extends METTAMRebateQueryBuilderExternalData
{
}

Method.Source:
public FieldId orderAccountJourTableFieldId()
{
    return fieldNum(METRebateScanSupplierTable, CustAccount);
}

public FieldId invoiceAccountJourTableFieldId()
{
    return fieldNum(METRebateScanSupplierTable, CustAccount);
}

protected FieldId accountMainTableFieldId()
{
    return fieldNum(CustTable, AccountNum);
}

/// <summary>
/// Add extra filters for the external sales data
/// </summary>
protected void addTransRange()
{
    // only select records with a customer account
    // Standard will do the price attribute header filtering in GUPRebateMatchingHelper\checkIfPricingAttributesAreMatched()
    query.dataSourceTable(tableNum(METRebateScanSupplierTable)).addRange(fieldNum(METRebateScanSupplierTable, CustAccount)).value(SysQuery::valueNotEmptyString());
    query.dataSourceTable(tableNum(METRebateScanSupplierTable)).addRange(fieldNum(METRebateScanSupplierTable, VendAccount)).value(SysQuery::valueEmptyString());

    super();
}
